    c = R.clamps(c, f_channel, 0, 3)

    {%Benchtable.TableChatEvent{channel: min(max(f_channel, 0), 3), speaker: f_speaker}, c, m}
  end

  # A RUN OF TableChatEvent: the LIVE elements walked into a list, the count riding beside
  # it, and not a byte of the slack behind them read. Several elements per clause
  # where the record is small, consed onto the recursive tail in order, no reverse.
  # THE UNROLLED CLAUSE IS THE SAME CLAUSE k TIMES — the same clamps, the same
  # counters — so it saves the match and the call and never a bound.
  def table_chat_event_fixed_list(_bin, 0, c, m), do: {[], c, m}

  def table_chat_event_fixed_list(
        <<f_channel_0::little-signed-32, f_speaker_0::little-unsigned-32,
          f_channel_1::little-signed-32, f_speaker_1::little-unsigned-32,
          f_channel_2::little-signed-32, f_speaker_2::little-unsigned-32,
          f_channel_3::little-signed-32, f_speaker_3::little-unsigned-32,
          f_channel_4::little-signed-32, f_speaker_4::little-unsigned-32,
          f_channel_5::little-signed-32, f_speaker_5::little-unsigned-32,
          f_channel_6::little-signed-32, f_speaker_6::little-unsigned-32,
          f_channel_7::little-signed-32, f_speaker_7::little-unsigned-32, rest::binary>>,
        n,
        c,
        m
      )
      when n >= 8 do
    c = R.clamps(c, f_channel_0, 0, 3)
    v0 = %Benchtable.TableChatEvent{channel: min(max(f_channel_0, 0), 3), speaker: f_speaker_0}
    c = R.clamps(c, f_channel_1, 0, 3)
    v1 = %Benchtable.TableChatEvent{channel: min(max(f_channel_1, 0), 3), speaker: f_speaker_1}
    c = R.clamps(c, f_channel_2, 0, 3)
    v2 = %Benchtable.TableChatEvent{channel: min(max(f_channel_2, 0), 3), speaker: f_speaker_2}
    c = R.clamps(c, f_channel_3, 0, 3)
    v3 = %Benchtable.TableChatEvent{channel: min(max(f_channel_3, 0), 3), speaker: f_speaker_3}
    c = R.clamps(c, f_channel_4, 0, 3)
    v4 = %Benchtable.TableChatEvent{channel: min(max(f_channel_4, 0), 3), speaker: f_speaker_4}
    c = R.clamps(c, f_channel_5, 0, 3)
    v5 = %Benchtable.TableChatEvent{channel: min(max(f_channel_5, 0), 3), speaker: f_speaker_5}
    c = R.clamps(c, f_channel_6, 0, 3)
    v6 = %Benchtable.TableChatEvent{channel: min(max(f_channel_6, 0), 3), speaker: f_speaker_6}
    c = R.clamps(c, f_channel_7, 0, 3)
    v7 = %Benchtable.TableChatEvent{channel: min(max(f_channel_7, 0), 3), speaker: f_speaker_7}
    {tail, c, m} = table_chat_event_fixed_list(rest, n - 8, c, m)
    {[v0, v1, v2, v3, v4, v5, v6, v7 | tail], c, m}
  end

  def table_chat_event_fixed_list(
        <<f_channel::little-signed-32, f_speaker::little-unsigned-32, rest::binary>>,
        n,
        c,
        m
      ) do
    c = R.clamps(c, f_channel, 0, 3)

    v = %Benchtable.TableChatEvent{channel: min(max(f_channel, 0), 3), speaker: f_speaker}
    {tail, c, m} = table_chat_event_fixed_list(rest, n - 1, c, m)
    {[v | tail], c, m}
  end

  # TablePickupEvent's body: 8 bytes, the values in DECLARED ORDER, every field at its
  # declared storage width, nothing padded between fields.
  def table_pickup_event_fixed_write_body(value),
    do: table_pickup_event_fixed_write_into(value, <<>>)

  # TablePickupEvent's body APPENDED to `acc`: the value destructured once, then one append per
  # run of scalars, one per element of every array, and the slack as zero segments.
  def table_pickup_event_fixed_write_into(value, acc) do
    %{item_id: v_item_id, amount: v_amount} = value

    acc =
      <<acc::binary, R.fits(v_item_id, 32, false)::little-unsigned-32,
        R.ranged(v_amount, @r_table_pickup_event_amount)::little-signed-32>>

    acc
  end

  # TablePickupEvent's projection: ONE binary pattern match over its 8 bytes of record
  # image, the struct it makes, the `clamped` it moved and the content flag.
  def table_pickup_event_fixed_decode(bin, c, m \\ false)

