  # TableMixed's body: 1224 bytes, the values in DECLARED ORDER, every field at its
  # declared storage width, nothing padded between fields.
  def table_mixed_fixed_write_body(value), do: table_mixed_fixed_write_into(value, <<>>)

  # TableMixed's body APPENDED to `acc`: the value destructured once, then one append per
  # run of scalars, one per element of every array, and the slack as zero segments.
  def table_mixed_fixed_write_into(value, acc) do
    %{
      protocol_magic: v_protocol_magic,
      sequence: v_sequence,
      ack_sequence: v_ack_sequence,
      ack_bits: v_ack_bits,
      session_id: v_session_id,
      client_id: v_client_id,
      nonce: v_nonce,
      world_time: v_world_time,
      frame_tick: v_frame_tick,
      server_time: v_server_time,
      entities: v_entities,
      stats: v_stats,
      game_event: v_game_event,
      loadout: v_loadout,
      player_name: v_player_name,
      payload: v_payload,
      aim_x: v_aim_x,
      aim_y: v_aim_y,
      aim_z: v_aim_z,
      recoil: v_recoil,
      drift: v_drift,
      wide_key: v_wide_key,
      flux: v_flux,
      ping: v_ping,
      crc_hint: v_crc_hint,
      has_extra: v_has_extra,
      extra: v_extra,
      idle_ticks: v_idle_ticks
    } = value

    acc =
      <<acc::binary, R.fits(v_protocol_magic, 16, false)::little-unsigned-16,
        R.fits(v_sequence, 32, false)::little-unsigned-32,
        R.ranged(v_ack_sequence, @r_table_mixed_ack_sequence)::little-signed-32,
        R.fits(v_ack_bits, 32, false)::little-unsigned-32,
        R.fits(v_session_id, 64, false)::little-unsigned-64,
        R.fits(v_client_id, 32, false)::little-unsigned-32,
        R.ranged(v_nonce, @r_table_mixed_nonce)::little-unsigned-64,
        R.ranged(v_world_time, @r_table_mixed_world_time)::little-signed-64,
        R.fits(v_frame_tick, 64, false)::little-unsigned-64,
        R.f32_bits(v_server_time)::little-unsigned-32>>

    n_entities = R.count(v_entities, 1, 8)
    acc = <<acc::binary, n_entities::little-signed-32>>
    acc = R.each(v_entities, acc, &table_entity_fixed_write_into/2)
    acc = <<acc::binary, 0::size((8 - n_entities) * 51)-unit(8)>>
    n_stats = R.count(v_stats, 0, 80)
    acc = <<acc::binary, n_stats::little-signed-32>>
    acc = R.each(v_stats, acc, &table_stat_fixed_write_into/2)
    acc = <<acc::binary, 0::size((80 - n_stats) * 8)-unit(8)>>
    acc = table_event_fixed_write_into(v_game_event, acc)
    n_loadout = R.count(v_loadout, 0, 4)

    acc =
      R.each(v_loadout, acc, fn e, acc ->
        <<acc::binary, R.fits(e, 8, false)::little-unsigned-8>>
      end)

    acc =
      <<acc::binary, 0::size((4 - n_loadout) * 1)-unit(8),
        byte_size(v_player_name)::little-signed-32, v_player_name::binary,
        0::size(R.text_slack(v_player_name, 15))-unit(8), byte_size(v_payload)::little-signed-32,
        v_payload::binary, 0::size(R.text_slack(v_payload, 16))-unit(8),
        R.f32_bits(v_aim_x)::little-unsigned-32, R.f32_bits(v_aim_y)::little-unsigned-32,
        R.f32_bits(v_aim_z)::little-unsigned-32, R.f32_bits(v_recoil)::little-unsigned-32,
        R.f64_bits(v_drift)::little-unsigned-64,
        R.fits(v_wide_key, 64, false)::little-unsigned-64,
        R.ranged(v_flux, @r_table_mixed_flux)::little-signed-64,
        R.f32_bits(v_ping)::little-unsigned-32, R.fits(v_crc_hint, 32, false)::little-unsigned-32,
        if(v_has_extra, do: 1, else: 0)::unsigned-8,
        R.ranged(v_extra, @r_table_mixed_extra)::little-signed-32,
        R.ranged(v_idle_ticks, @r_table_mixed_idle_ticks)::little-signed-32>>

    acc
  end

  # TableMixed's projection: ONE binary pattern match over its 1224 bytes of record
  # image, the struct it makes, the `clamped` it moved and the content flag.
  def table_mixed_fixed_decode(bin, c, m \\ false)

  def table_mixed_fixed_decode(
        <<f_protocol_magic::little-unsigned-16, f_sequence::little-unsigned-32,
          f_ack_sequence::little-signed-32, f_ack_bits::little-unsigned-32,
          f_session_id::little-unsigned-64, f_client_id::little-unsigned-32,
          f_nonce::little-unsigned-64, f_world_time::little-signed-64,
          f_frame_tick::little-unsigned-64, f_server_time::little-unsigned-32,
          n_entities::little-signed-32, b_entities::binary-size(408), n_stats::little-signed-32,
          b_stats::binary-size(640), b_game_event::binary-size(14),
          f_loadout_0::little-unsigned-8, f_loadout_1::little-unsigned-8,
          f_loadout_2::little-unsigned-8, f_loadout_3::little-unsigned-8,
          n_player_name::little-signed-32, b_player_name::binary-size(15),
          n_payload::little-signed-32, b_payload::binary-size(16), f_aim_x::little-unsigned-32,
          f_aim_y::little-unsigned-32, f_aim_z::little-unsigned-32, f_recoil::little-unsigned-32,
          f_drift::little-unsigned-64, f_wide_key::little-unsigned-64, f_flux::little-signed-64,
          f_ping::little-unsigned-32, f_crc_hint::little-unsigned-32, f_has_extra::unsigned-8,
          f_extra::little-signed-32, f_idle_ticks::little-signed-32, _::binary>>,
        c,
        m
      ) do
    c = R.clamps(c, f_ack_sequence, 0, 65_535)
    c = R.clamps(c, f_nonce, 1, 9_223_372_036_854_775_807)
    c = R.clamps(c, f_world_time, -1_000_000_000_000, 1_000_000_000_000)
    c = R.fclamps(c, R.f32_value(f_server_time), 0.0, 65535.0)
    c = R.clamps(c, n_entities, 0, 8)
    {l_entities, c, m} = table_entity_fixed_list(b_entities, min(max(n_entities, 0), 8), c, m)
    c = R.clamps(c, n_stats, 0, 80)
    {l_stats, c, m} = table_stat_fixed_list(b_stats, min(max(n_stats, 0), 80), c, m)
    {f_game_event, c, m} = table_event_fixed_decode(b_game_event, c, m)
    c = R.clamps(c, n_player_name, 0, 15)

    {t_player_name, m} =
      R.text(binary_part(b_player_name, 0, min(max(n_player_name, 0), 15)), <<>>, m, true)

    c = R.clamps(c, n_payload, 0, 16)
    c = R.fclamps(c, R.f32_value(f_aim_x), -1.0, 1.0)
    c = R.fclamps(c, R.f32_value(f_aim_y), -1.0, 1.0)
    c = R.fclamps(c, R.f32_value(f_aim_z), -1.0, 1.0)
    c = R.clamps(c, f_flux, -1_000_000_000_000_000_000, 1_000_000_000_000_000_000)
    c = R.fclamps(c, R.f32_value(f_ping), 0.0, 250.0)
    c = R.clamps(c, f_extra, 0, 255)
    c = R.clamps(c, f_idle_ticks, 0, 15)

    {%Benchtable.TableMixed{
       protocol_magic: f_protocol_magic,
       sequence: f_sequence,
       ack_sequence: min(max(f_ack_sequence, 0), 65_535),
       ack_bits: f_ack_bits,
       session_id: f_session_id,
       client_id: f_client_id,
       nonce: min(max(f_nonce, 1), 9_223_372_036_854_775_807),
       world_time: min(max(f_world_time, -1_000_000_000_000), 1_000_000_000_000),
       frame_tick: f_frame_tick,
       server_time: R.fclamp(R.f32_value(f_server_time), 0.0, 65535.0),
       entities: l_entities,
       stats: l_stats,
       game_event: f_game_event,
       loadout: [f_loadout_0, f_loadout_1, f_loadout_2, f_loadout_3],
       player_name: t_player_name,
       payload: binary_part(b_payload, 0, min(max(n_payload, 0), 16)),
       aim_x: R.fclamp(R.f32_value(f_aim_x), -1.0, 1.0),
       aim_y: R.fclamp(R.f32_value(f_aim_y), -1.0, 1.0),
       aim_z: R.fclamp(R.f32_value(f_aim_z), -1.0, 1.0),
       recoil: R.f32_value(f_recoil),
       drift: R.f64_value(f_drift),
       wide_key: f_wide_key,
       flux: min(max(f_flux, -1_000_000_000_000_000_000), 1_000_000_000_000_000_000),
       ping: R.fclamp(R.f32_value(f_ping), 0.0, 250.0),
       crc_hint: f_crc_hint,
       has_extra: f_has_extra != 0,
       extra: min(max(f_extra, 0), 255),
       idle_ticks: min(max(f_idle_ticks, 0), 15)
     }, c, m}
  end

  # A RUN OF TableMixed: the LIVE elements walked into a list, the count riding beside
  # it, and not a byte of the slack behind them read. Several elements per clause
  # where the record is small, consed onto the recursive tail in order, no reverse.
  # THE UNROLLED CLAUSE IS THE SAME CLAUSE k TIMES — the same clamps, the same
  # counters — so it saves the match and the call and never a bound.
  def table_mixed_fixed_list(_bin, 0, c, m), do: {[], c, m}

  def table_mixed_fixed_list(<<e::binary-size(1224), rest::binary>>, n, c, m) do
    {v, c, m} = table_mixed_fixed_decode(e, c, m)
    {tail, c, m} = table_mixed_fixed_list(rest, n - 1, c, m)
    {[v | tail], c, m}
  end

  # ---- TableEntity, the fixed form ----

  # MEASURE IS A CONSTANT on this form: the body is the same size for every
  # value the type can hold (docs/SPEC-TABLES.md §3.4).
  @table_entity_body_bytes 51
  @table_entity_record_bytes 59
  @table_entity_hash 0x45D64DB53CE7AC1F

