7\x0E\x04\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x06\x01\x00\x00\x00\x00\x00\x00\x00\x6E\xE8\xF8\x2C\x54\x2F\xA6\x13\x0C\x13\x00\x00\x00\x00\x00\x00\x00\xE5\xE9\xB5\x63\xD0\xA9\xB8\xCF\x0E\x14\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x06\x01\x00\x00\x00\x00\x00\x00\x00\xC9\x96\x42\xE2\xE5\x7B\xAF\xDB\x0A\x04\x00\x00\x00\x00\x00\x00\x00\x16\x95\x42\xE2\xE5\x7A\xAF\xDB\x0A\x04\x00\x00\x00\x00\x00\x00\x00\x63\x93\x42\xE2\xE5\x79\xAF\xDB\x0A\x04\x00\x00\x00\x00\x00\x00\x00\x57\xE4\xE2\xF7\xFF\x31\xEF\x9C\x0A\x04\x00\x00\x00\x00\x00\x00\x00\x04\x6C\x1F\x34\xC9\xF9\xB3\x5A\x0B\x08\x00\x00\x00\x00\x00\x00\x00\x16\xAF\x1F\x46\x80\x85\x34\xA3\x09\x08\x00\x00\x00\x00\x00\x00\x00\x42\x26\xAF\x08\x79\xDD\x1B\xD6\x05\x08\x00\x00\x00\x00\x00\x00\x00\xA9\x07\x33\xC5\x0D\xE0\x30\xBF\x0A\x04\x00\x00\x00\x00\x00\x00\x00\x5F\x51\xD8\xCC\x27\x65\x0D\x56\x08\x04\x00\x00\x00\x00\x00\x00\x00\x72\x86\xFD\x6C\x17\x92\x82\xC0\x01\x01\x00\x00\x00\x00\x00\x00\x00\x69\xCB\x79\xA9\x12\xEE\x29\xFD\x04\x04\x00\x00\x00\x00\x00\x00\x00\xFE\xBC\x8C\xAA\xC0\x1A\x10\x78\x04\x04\x00\x00\x00\x00\x00\x00\x00",
      layout_bytes: 1279,
      record_bytes: 1232
    }
  }

  # THE FLOOR: 1 + the highest RETIRED index, 0 when none is (§5.2). Below it
  # a layout this build once served is retired and the answer is
  # `:layout_unsupported` — upgrade the client — rather than `:layout_newer`.
  @table_mixed_floor 0

  # THE RETIRED HASHES and the operator's own sentence for each, which is what
  # `:layout_unsupported` means in words.
  @table_mixed_retired []

  def table_mixed_fixed_body_bytes, do: @table_mixed_body_bytes
  def table_mixed_fixed_record_bytes, do: @table_mixed_record_bytes
  def table_mixed_fixed_hash, do: @table_mixed_hash
  def table_mixed_fixed_layout, do: @table_mixed_layout
  def table_mixed_fixed_plan, do: @table_mixed_plan
  def table_mixed_fixed_prefill, do: @table_mixed_prefill
  def table_mixed_fixed_dst, do: @table_mixed_dst
  def table_mixed_fixed_known, do: @table_mixed_known
  def table_mixed_fixed_floor, do: @table_mixed_floor
  def table_mixed_fixed_retired, do: @table_mixed_retired

  # A FILE: THE HEADER (docs/SPEC-TABLES.md §3, one rule for all five forms)
  # — the form byte, seven reserved zero bytes, the LAYOUT HASH at 8 — then the
  # layout behind its u32 length, then the records to the end of it.
  def table_mixed_fixed_measure(count) do
    R.file_header_bytes() + byte_size(@table_mixed_layout) + count * @table_mixed_record_bytes
  end

  # THE WRITE: the hash, then the body APPENDED to it. There is no measuring
  # pass, no id interning, no trailer, no second walk and no flatten: a file
  # of records is one binary every record was appended to in place.
  def table_mixed_fixed_record(value) do
    table_mixed_fixed_write_into(value, <<@table_mixed_hash::little-unsigned-64>>)
  end

  def table_mixed_fixed_save(values) when is_list(values) do
    head =
      <<R.file_header(@table_mixed_hash, byte_size(@table_mixed_layout))::binary,
        @table_mixed_layout::binary>>

    R.each(values, head, fn value, acc ->
      table_mixed_fixed_write_into(value, <<acc::binary, @table_mixed_hash::little-unsigned-64>>)
    end)
  end

  @doc """
  Read a form-3 FILE of TableMixed records.

  `{:ok, values, report}` or `{:error, reason, report}`, the reason BY NAME.
  Hostile bytes never raise: this is the family read verdict, the same one
  the packet codec answers with.

  THE SAME LOOP RUNS OVER THE SAME PLAN whether the writer is this build or
  another, and the only thing that differs is which plan it was handed.
  """
  def table_mixed_fixed_load(data, opts \\ []) when is_binary(data) do
    report = R.report()

    # A FORM BYTE THIS BUILD DOES NOT CARRY IS A REFUSAL BY NAME and never
    # damage: nothing is decoded and no counter moves. The registry is
    # ORDERED, so the name says which direction (§3).
    case R.read_file_header(data) do
      {:ok, stated, layout, records} ->
        table_mixed_fixed_records(stated, layout, records, report, opts)

      {:error, :malformed} ->
        # STEP 1: a file shorter than a header is the RESIDUE and not a bucket
        # a named rule falls into — `malformed`, and no reason (§5.3).
        {:error, :malformed, %{report | malformed: true}}

      {:error, why} ->
        {:error, why, report}
    end
  end

  # THE READ: §5.3's ELEVEN STEPS, IN ORDER. The header's hash is TAKEN AS
  # GIVEN — the definitions digest is not on the wire, so the hash cannot be
  # re-derived from the layout behind it — then the LINEAGE SELECT, then the
  # floor, then the BYTE COMPARISON against the bytes the lock recorded.
  # NOTHING PARSES A STRANGER'S LAYOUT, ON ANY PATH.
  defp table_mixed_fixed_records(stated, layout, records, report, opts) do
    copy = Keyword.get(opts, :copy, false)
    cap = Keyword.get(opts, :plan_capacity, R.plan_capacity())
    bcap = Keyword.get(opts, :batch_capacity, R.batch_capacity())

    # A CALLER'S `plan:` IS ACCEPTED AND NOT READ (§5.9 #16): §5.6 retires
    # MECHANISMS and not API, so the argument keeps its place and the plan a
    # load runs is THE BUILD'S. `plan_capacity:` stays what §5.9 #5 says it is
    # — a CAPACITY DECLARATION, checked and never written through.
    _ = Keyword.get(opts, :plan)

    case R.select(@table_mixed_known, @table_mixed_floor, stated, layout) do
      {:error, why, file_hash} ->
        # BOTH LAYOUT REFUSALS REPORT THE FILE'S HASH (§5.9 #7), on
        # `layout_hash`, LAST on the report and zero on every other path
        # (§5.9 #15). REFUSE IS TOTAL: no counter moves, nothing is decoded and
        # not one destination byte is written — the prefill included.
        {:error, why, %{report | layout_hash: file_hash}}

      {:ok, i} ->
        table_mixed_fixed_lane(i, records, stated, report, cap, bcap, copy)
    end
  end

  # THE PLAN IS THE BUILD'S, one per lineage entry, laid down at MODULE LOAD
  # from the lock's own bytes (§5.9 #3). Nothing on this path compiles and
  # nothing on it can fail for want of a plan: an entry whose plan would not
  # build carries its own refusal reason, and this is where it is read.
  defp table_mixed_fixed_lane(i, records, hash, report, cap, bcap, copy) do
    case R.lineage_lane(__MODULE__, :table_mixed, i) do
      :identity ->
        table_mixed_fixed_run(
          @table_mixed_plan,
          @table_mixed_body_bytes,
          records,
          hash,
          report,
          copy,
          bcap,
          {0, 0}
        )

      {:ok, _plan, _size, made, _u, _k} when made > cap ->
        # THE DECLARED CAPACITY A BUILD HOLDS AN ENTRY TO IS REAL (§5.9 #4) and
        # the NAME is the contract (§5.9 #5).
        {:error, :plan_too_large, report}

      {:ok, plan, size, _made, u, k} ->
        table_mixed_fixed_run(plan, size, records, hash, report, copy, bcap, {u, k})

      {:error, why} ->
        {:error, why, report}
    end
  end

  # ONE PREFILL-AND-PROJECT PER RECORD, and the per-record hash checked BEFORE
  # a byte is landed. Neither plan clamps a ranged integer: the generated
  # projection holds the bound after the loop, the same pass for either plan.
  defp table_mixed_fixed_run(plan, size, records, hash, report, copy, bcap, census) do
    {census_u, census_k} = census

    # §5.3 STEP 10, BEFORE A RECORD IS SPLIT OFF: `n := rest / record_bytes`,
    # and a batch past the caller's room is a REFUSAL BY NAME. Step 9 runs
    # first and owns the ragged tail, so a `rest` that is not a whole number
    # of records passes this and the split reports `malformed`.
    # A CONTENT VIOLATION IN THE USED UNITS REFUSES THE WHOLE READ BY NAME
    # (§4.5 fix 11): `R.text`, `R.wtext` and the compiled plan's text op all
    # THROW `{:refuse, :text_ill_formed}`, and this is where the uniform
    # refusal is caught, with no destination byte landed and every counter
    # left at zero.
    try do
      with :ok <- R.batch_within(byte_size(records), size + 8, bcap),
           {:ok, bodies} <- table_mixed_fixed_split(records, hash, size, []) do
        {values, report} =
          Enum.map_reduce(bodies, report, fn body, report ->
            {image, report} = R.run(plan, R.detach(body, copy), @table_mixed_prefill, report)
            {value, c, m} = table_mixed_fixed_decode(image, 0, false)
            {value, R.damaged(R.clamped(report, c), m)}
          end)

        # THE COMPILE CENSUS LANDS ONCE, AFTER THE LOOP, and only on a read that
        # RETURNS (§5.9 #6): §5.4 says once per endpoint and never per record, and a
        # refusal that came after would have moved a counter.
        {:ok, values, R.census(report, census_u, census_k)}
      else
        {:error, :malformed} -> {:error, :malformed, %{report | malformed: true}}
        {:error, why} -> {:error, why, report}
      end
    catch
      :throw, {:refuse, why} -> {:error, why, report}
    end
  end

  # THE RECORDS FILL THE REST OF THE FILE and there is no count: a reader knows
  # the record size from the layout, so the count is arithmetic. BYTES LEFT
  # OVER ARE `malformed`, which is §3's rule for the same reason.
  defp table_mixed_fixed_split(<<>>, _hash, _size, acc), do: {:ok, :lists.reverse(acc)}

  defp table_mixed_fixed_split(records, hash, size, acc) do
    case records do
      <<h::little-unsigned-64, body::binary-size(^size), rest::binary>> when h == hash ->
        table_mixed_fixed_split(rest, hash, size, [body | acc])

      <<_::little-unsigned-64, _::binary-size(^size), _::binary>> ->
        # A RECORD WHOSE HASH NAMES NO LAYOUT THIS READER HOLDS IS A REFUSAL BY
        # NAME, never a guess and never damage.
        {:error, :no_layout}

      _ ->
        {:error, :malformed}
    end
  end

  # ONE PLAN PER LINEAGE ENTRY, BUILT AT MODULE LOAD from the lock's own bytes
  # and held in `:persistent_term` (§5.9 #3, #20). The BEAM runs `@on_load`
  # before any caller can reach this module, so the build is OFF EVERY LOAD
  # PATH and a load can never fail for want of a plan. IT CANNOT THROW: every
  # entry is a LANE WITH ITS OWN REFUSAL REASON, so the hook always answers
  # `:ok` and the module always loads.
  @on_load :__fixed_lineage__

  @doc false
  def __fixed_lineage__ do
    R.lineage_init(
      __MODULE__,
      :table_entity,
      @table_entity_known,
      @table_entity_hash,
      @table_entity_layout,
      @table_entity_dst,
      R.plan_capacity()
    )

    R.lineage_init(
      __MODULE__,
      :table_stat,
      @table_stat_known,
      @table_stat_hash,
      @table_stat_layout,
      @table_stat_dst,
      R.plan_capacity()
    )

    R.lineage_init(
      __MODULE__,
      :table_mixed,
      @table_mixed_known,
      @table_mixed_hash,
      @table_mixed_layout,
      @table_mixed_dst,
      R.plan_capacity()
    )

    :ok
  end
end
